BEGIN;
CREATE TABLE IF NOT EXISTS citizen_tenants(id UUID PRIMARY KEY,name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS citizen_tenant_members(tenant_id UUID REFERENCES citizen_tenants(id),user_id INTEGER NOT NULL,role TEXT NOT NULL CHECK(role IN('owner','knowledge_manager','reviewer','service_officer','member')),active BOOLEAN NOT NULL DEFAULT true,PRIMARY KEY(tenant_id,user_id));
CREATE TABLE IF NOT EXISTS citizen_idempotency(actor_id INTEGER NOT NULL,key TEXT NOT NULL,response JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(actor_id,key));
CREATE TABLE IF NOT EXISTS citizen_knowledge_sources(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES citizen_tenants(id),name TEXT NOT NULL,origin_uri TEXT NOT NULL,classification TEXT NOT NULL CHECK(classification IN('public','internal','restricted')),checksum TEXT NOT NULL,idempotency_key TEXT NOT NULL,created_by INTEGER NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS citizen_documents(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES citizen_tenants(id),source_id BIGINT NOT NULL REFERENCES citizen_knowledge_sources(id),title TEXT NOT NULL,content TEXT NOT NULL,content_checksum TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('pending_review','quarantined','approved','rejected')),injection_signals JSONB NOT NULL DEFAULT '[]',created_by INTEGER NOT NULL,reviewed_by INTEGER,review_reason TEXT,reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS citizen_answers(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES citizen_tenants(id),question TEXT NOT NULL,answer TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('grounded_draft','escalated')),evidence JSONB NOT NULL DEFAULT '[]',idempotency_key TEXT NOT NULL,created_by INTEGER NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS citizen_escalations(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES citizen_tenants(id),answer_id BIGINT REFERENCES citizen_answers(id),reason TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('open','assigned','resolved')),assignee_id INTEGER,resolution TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS citizen_tool_actions(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES citizen_tenants(id),action_type TEXT NOT NULL,payload JSONB NOT NULL,state TEXT NOT NULL CHECK(state IN('pending_approval','approved_for_dispatch','dispatched','failed','cancelled')),requested_by INTEGER NOT NULL,approved_by INTEGER,approval_reason TEXT,approved_at TIMESTAMPTZ,provider_reference TEXT,failure_code TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS citizen_audit_events(id BIGSERIAL PRIMARY KEY,tenant_id UUID NOT NULL REFERENCES citizen_tenants(id),actor_id INTEGER NOT NULL,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,details JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS citizen_documents_tenant_status_idx ON citizen_documents(tenant_id,status);
CREATE INDEX IF NOT EXISTS citizen_audit_tenant_time_idx ON citizen_audit_events(tenant_id,created_at DESC);
COMMIT;
